VALUES ('7b2cf9ad-20f5-4669-8537-9c0aaf858120', 'd89d8eb1-6f66-426a-9573-ff0b297469c2', '[{"parameters": {"httpMethod": "POST", "path": "ai-guide", "responseMode": "lastNode", "options": {}}, "id": "trigger", "name": "Webhook", "type": "n8n-nodes-base.webhook", "typeVersion": 1, "position": [200, 300]}, {"parameters": {"model": "gpt-4", "promptType": "chat", "promptMessages": [{"role": "system", "message": "Tu es le **Guide IA** de la plateforme n8n-geospatial, un assistant intelligent qui aide les utilisateurs \u00e0 naviguer dans le syst\u00e8me.\n\n## Architecture du Syst\u00e8me\nn8n-geospatial est une plateforme compl\u00e8te de gestion de donn\u00e9es g\u00e9ospatiales compos\u00e9e de :\n- **n8n** : Moteur d''automatisation et d''orchestration des workflows\n- **PostGIS** : Base de donn\u00e9es g\u00e9ographique pour le stockage des donn\u00e9es cadastrales et domaniales\n- **Serveur MCP** : Serveur Python exposant des outils g\u00e9ospatiaux avanc\u00e9s (port 5001)\n- **Agents IA sp\u00e9cialis\u00e9s** :\n  - Agent Cadastral : Recherche de parcelles, propri\u00e9taires, analyses spatiales\n  - Agent Domanial : Gestion des biens du domaine, \u00e9valuations, dossiers\n  - Agent Administrateur : Supervision et maintenance du syst\u00e8me\n\n## Ton R\u00f4le\n1. **Orienter** les utilisateurs vers l''agent ou le workflow appropri\u00e9\n2. **Expliquer** le fonctionnement du syst\u00e8me\n3. **Diagnostiquer** l''\u00e9tat du syst\u00e8me (base de donn\u00e9es, services)\n4. **Lister** les workflows et outils disponibles\n\n## Outils Disponibles\n- **list_workflows** : Affiche tous les workflows n8n disponibles\n- **check_db_status** : V\u00e9rifie l''\u00e9tat de la connexion PostGIS\n- **get_system_info** : R\u00e9cup\u00e8re les informations syst\u00e8me (version, uptime)\n\n## Conseils d''Utilisation\n- Pour les questions cadastrales \u2192 oriente vers l''Agent Cadastral\n- Pour la gestion du domaine \u2192 oriente vers l''Agent Domanial\n- Pour les probl\u00e8mes techniques \u2192 utilise tes outils de diagnostic\n- R\u00e9ponds toujours en fran\u00e7ais, de mani\u00e8re claire et professionnelle"}, {"role": "user", "message": "={{$json.body.message}}"}], "tools": [{"tool": {"name": "list_workflows"}}, {"tool": {"name": "check_db_status"}}, {"tool": {"name": "get_system_info"}}], "options": {}}, "id": "agent", "name": "Agent Guide", "type": "n8n-nodes-base.aiAgent", "typeVersion": 1, "position": [440, 300]}, {"parameters": {"operation": "executeQuery", "query": "SELECT id, name, active, created_at, updated_at FROM public.workflow_entity ORDER BY name ASC LIMIT 50;", "options": {}}, "id": "list_workflows", "name": "List Workflows", "type": "n8n-nodes-base.postgres", "typeVersion": 3.3, "position": [720, 100], "credentials": {"postgres": {"id": "n8n-postgres", "name": "n8n PostgreSQL"}}, "notes": "Outil IA: Liste tous les workflows disponibles dans n8n."}, {"parameters": {"operation": "executeQuery", "query": "SELECT version() as pg_version, PostGIS_Full_Version() as postgis_version, current_database() as database, pg_size_pretty(pg_database_size(current_database())) as db_size, (SELECT count(*) FROM cadastre.parcelles) as parcelles_count, (SELECT count(*) FROM domaine.biens) as biens_count;", "options": {}}, "id": "check_db_status", "name": "Check DB Status", "type": "n8n-nodes-base.postgres", "typeVersion": 3.3, "position": [720, 300], "credentials": {"postgres": {"id": "postgis-credentials", "name": "PostGIS Credentials"}}, "notes": "Outil IA: V\u00e9rifie l''\u00e9tat de la base de donn\u00e9es PostGIS."}, {"parameters": {"mode": "runOnceForAllItems", "jsCode": "const info = {\n  timestamp: new Date().toISOString(),\n  n8n_version: $env.N8N_VERSION || ''non disponible'',\n  node_version: process.version,\n  environment: $env.NODE_ENV || ''production'',\n  mcp_server_url: ''http://localhost:5001'',\n  webhooks: {\n    guide: ''/webhook/ai-guide'',\n    cadastral: ''/webhook/ai-cadastral'',\n    domanial: ''/webhook/ai-domanial''\n  },\n  status: ''op\u00e9rationnel''\n};\nreturn [{ json: info }];"}, "id": "get_system_info", "name": "Get System Info", "type": "n8n-nodes-base.code", "typeVersion": 2, "position": [720, 500], "notes": "Outil IA: Retourne les informations syst\u00e8me."}]', '{"trigger": {"main": [[{"node": "agent", "type": "main", "index": 0}]]}, "agent": {"main": [[{"node": "list_workflows", "type": "main", "index": 0}], [{"node": "check_db_status", "type": "main", "index": 1}], [{"node": "get_system_info", "type": "main", "index": 2}]]}, "list_workflows": {"main": [[{"node": "agent", "type": "main", "index": 0}]]}, "check_db_status": {"main": [[{"node": "agent", "type": "main", "index": 0}]]}, "get_system_info": {"main": [[{"node": "agent", "type": "main", "index": 0}]]}}', NOW());

