-- [AI Agent Cadastral]
INSERT INTO workflow_entity (id, name, active, nodes, connections, settings, "versionId", "createdAt", "updatedAt", "versionCounter")
VALUES ('d34b9557-114b-4dcf-9d47-e0537c67fd84', 'AI Agent Cadastral', true, '[{"parameters": {"httpMethod": "POST", "path": "ai-cadastral", "responseMode": "lastNode", "options": {}}, "id": "trigger", "name": "Webhook", "type": "n8n-nodes-base.webhook", "typeVersion": 1, "position": [200, 300]}, {"parameters": {"model": "gpt-4", "promptType": "chat", "promptMessages": [{"role": "system", "message": "Tu es l''Agent Cadastral IA, expert en donn\u00e9es cadastrales. Ton r\u00f4le est de r\u00e9pondre aux questions sur les parcelles, leurs propri\u00e9taires et leur localisation.\n\nOutils disponibles :\n- **search_parcelle_by_id**: Recherche une parcelle par son identifiant (ex: commune, section, num\u00e9ro).\n- **find_parcelles_nearby**: Trouve les parcelles dans un rayon autour d''un point g\u00e9ographique. Param\u00e8tres : ''x'', ''y'' (Lambert 93) et ''distance'' (en m\u00e8tres).\n- **get_proprietaire_info**: R\u00e9cup\u00e8re les informations du propri\u00e9taire pour une parcelle donn\u00e9e.\n- **get_stats_commune**: Obtient des statistiques sur une commune (nombre de parcelles, surface totale, etc.)."}, {"role": "user", "message": "={{$json.body.message}}"}], "tools": [{"tool": {"name": "search_parcelle_by_id"}}, {"tool": {"name": "find_parcelles_nearby"}}, {"tool": {"name": "get_proprietaire_info"}}, {"tool": {"name": "get_stats_commune"}}], "options": {}}, "id": "agent", "name": "Agent Cadastral", "type": "n8n-nodes-base.aiAgent", "typeVersion": 1, "position": [440, 300]}, {"parameters": {"operation": "executeQuery", "query": "SELECT id_parcelle, code_commune, section, numero, contenance, ST_AsGeoJSON(geom) as geometry FROM cadastre.parcelles WHERE code_commune = ''{{ $json.parameters.code_commune }}'' AND section = ''{{ $json.parameters.section }}'' AND numero = ''{{ $json.parameters.numero }}'' LIMIT 1;", "options": {}}, "id": "search_parcelle_by_id", "name": "Search Parcelle by ID", "type": "n8n-nodes-base.postgres", "typeVersion": 3.3, "position": [720, 100], "credentials": {"postgres": {"id": "postgis-credentials", "name": "PostGIS Credentials"}}, "notes": "Outil IA: Recherche une parcelle par son identifiant."}, {"parameters": {"command": "./scripts/analyse_spatiale.py --action buffer --params ''{{ JSON.stringify($json.parameters) }}''", "options": {}}, "id": "find_parcelles_nearby", "name": "Find Parcelles Nearby", "type": "n8n-nodes-base.executeCommand", "typeVersion": 2, "position": [720, 300], "notes": "Outil IA: Trouve les parcelles autour d''un point via un script Python."}, {"parameters": {"operation": "executeQuery", "query": "SELECT nom, prenom, adresse, code_droit FROM cadastre.proprietaires WHERE id_parcelle = ''{{ $json.parameters.id_parcelle }}'' ORDER BY nom;", "options": {}}, "id": "get_proprietaire_info", "name": "Get Propri\u00e9taire Info", "type": "n8n-nodes-base.postgres", "typeVersion": 3.3, "position": [720, 500], "credentials": {"postgres": {"id": "postgis-credentials", "name": "PostGIS Credentials"}}, "notes": "Outil IA: R\u00e9cup\u00e8re les infos du propri\u00e9taire d''une parcelle."}, {"parameters": {"command": "./scripts/analyse_spatiale.py --action stats_commune --params ''{{ JSON.stringify($json.parameters) }}''", "options": {}}, "id": "get_stats_commune", "name": "Get Stats Commune", "type": "n8n-nodes-base.executeCommand", "typeVersion": 2, "position": [720, 700], "notes": "Outil IA: Obtient des statistiques sur une commune."}]', '{"trigger": {"main": [[{"node": "agent", "type": "main", "index": 0}]]}, "agent": {"main": [[{"node": "search_parcelle_by_id", "type": "main", "index": 0}], [{"node": "find_parcelles_nearby", "type": "main", "index": 1}], [{"node": "get_proprietaire_info", "type": "main", "index": 2}], [{"node": "get_stats_commune", "type": "main", "index": 3}]]}, "search_parcelle_by_id": {"main": [[{"node": "agent", "type": "main", "index": 0}]]}, "find_parcelles_nearby": {"main": [[{"node": "agent", "type": "main", "index": 0}]]}, "get_proprietaire_info": {"main": [[{"node": "agent", "type": "main", "index": 0}]]}, "get_stats_commune": {"main": [[{"node": "agent", "type": "main", "index": 0}]]}}', '{}', 'c394353e-df2b-466d-b61a-4657ee88ea3a', NOW(), NOW(), 1);

