osition": [720, 100], "credentials": {"postgres": {"id": "postgis-credentials", "name": "PostGIS Credentials"}}, "notes": "Outil IA: Recherche une parcelle par son identifiant."}, {"parameters": {"command": "./scripts/analyse_spatiale.py --action buffer --params ''{{ JSON.stringify($json.parameters) }}''", "options": {}}, "id": "find_parcelles_nearby", "name": "Find Parcelles Nearby", "type": "n8n-nodes-base.executeCommand", "typeVersion": 2, "position": [720, 300], "notes": "Outil IA: Trouve les parcelles autour d''un point via un script Python."}, {"parameters": {"operation": "executeQuery", "query": "SELECT nom, prenom, adresse, code_droit FROM cadastre.proprietaires WHERE id_parcelle = ''{{ $json.parameters.id_parcelle }}'' ORDER BY nom;", "options": {}}, "id": "get_proprietaire_info", "name": "Get Propri\u00e9taire Info", "type": "n8n-nodes-base.postgres", "typeVersion": 3.3, "position": [720, 500], "credentials": {"postgres": {"id": "postgis-credentials", "name": "PostGIS Credentials"}}, "notes": "Outil IA: R\u00e9cup\u00e8re les infos du propri\u00e9taire d''une parcelle."}, {"parameters": {"command": "./scripts/analyse_spatiale.py --action stats_commune --params ''{{ JSON.stringify($json.parameters) }}''", "options": {}}, "id": "get_stats_commune", "name": "Get Stats Commune", "type": "n8n-nodes-base.executeCommand", "typeVersion": 2, "position": [720, 700], "notes": "Outil IA: Obtient des statistiques sur une commune."}]', '{"trigger": {"main": [[{"node": "agent", "type": "main", "index": 0}]]}, "agent": {"main": [[{"node": "search_parcelle_by_id", "type": "main", "index": 0}], [{"node": "find_parcelles_nearby", "type": "main", "index": 1}], [{"node": "get_proprietaire_info", "type": "main", "index": 2}], [{"node": "get_stats_commune", "type": "main", "index": 3}]]}, "search_parcelle_by_id": {"main": [[{"node": "agent", "type": "main", "index": 0}]]}, "find_parcelles_nearby": {"main": [[{"node": "agent", "type": "main", "index": 0}]]}, "get_proprietaire_info": {"main": [[{"node": "agent", "type": "main", "index": 0}]]}, "get_stats_commune": {"main": [[{"node": "agent", "type": "main", "index": 0}]]}}', NOW());

