VALUES ('f69ba866-49e4-43ca-89b5-9dcb4b0e2151', 'AI Agent Domanial', true, '[{"parameters": {"httpMethod": "POST", "path": "ai-domanial", "responseMode": "lastNode", "options": {}}, "id": "trigger", "name": "Webhook", "type": "n8n-nodes-base.webhook", "typeVersion": 1, "position": [200, 300]}, {"parameters": {"model": "gpt-4", "promptType": "chat", "promptMessages": [{"role": "system", "message": "Tu es l''Agent Domanial IA. Ton expertise porte sur la gestion des biens fonciers (domaine), les \u00e9valuations et l''instruction des dossiers administratifs.\n\nOutils disponibles :\n- **search_bien_by_ref**: Recherche un bien du domaine par sa r\u00e9f\u00e9rence unique.\n- **analyse_bien_details**: Fournit une analyse spatiale et de valeur d\u00e9taill\u00e9e pour un bien via son ID.\n- **search_dossier_by_ref**: Recherche un dossier d''instruction par sa r\u00e9f\u00e9rence."}, {"role": "user", "message": "={{$json.body.message}}"}], "tools": [{"tool": {"name": "search_bien_by_ref"}}, {"tool": {"name": "analyse_bien_details"}}, {"tool": {"name": "search_dossier_by_ref"}}], "options": {}}, "id": "agent", "name": "Agent Domanial", "type": "n8n-nodes-base.aiAgent", "typeVersion": 1, "position": [440, 300]}, {"parameters": {"operation": "executeQuery", "query": "SELECT id, reference, type_bien, designation, adresse, code_commune, surface, valeur_venale, statut, date_modification FROM domaine.biens WHERE reference ILIKE ''{{ $json.parameters.reference }}'' LIMIT 1;", "options": {}}, "id": "search_bien_by_ref", "name": "Search Bien by Ref", "type": "n8n-nodes-base.postgres", "typeVersion": 3.3, "position": [740, 100], "credentials": {"postgres": {"id": "postgis-credentials", "name": "PostGIS Credentials"}}, "notes": "Outil IA: Recherche un bien par sa r\u00e9f\u00e9rence."}, {"parameters": {"url": "=http://geo-api:8000/api/v1/biens/{{ $json.parameters.bien_id }}/analyse", "authentication": "predefinedCredential", "nodeCredential": {"type": "n8n-nodes-base.oAuth2JwtBearer", "data": {"name": "JWT Geo API", "accessTokenUrl": "http://geo-api:8000/auth/token", "clientId": "gestionnaire", "clientSecret": "cadastre2024", "scope": "biens:read"}}, "options": {}}, "id": "analyse_bien_details", "name": "Analyse Bien Details", "type": "n8n-nodes-base.httpRequest", "typeVersion": 4.1, "position": [740, 300], "notes": "Outil IA: Appelle l''API pour une analyse d\u00e9taill\u00e9e du bien."}, {"parameters": {"operation": "executeQuery", "query": "SELECT id, reference, type_dossier, statut, priorite, objet, instructeur, date_limite FROM traitement.dossiers WHERE reference ILIKE ''{{ $json.parameters.reference }}'' LIMIT 1;", "options": {}}, "id": "search_dossier_by_ref", "name": "Search Dossier by Ref", "type": "n8n-nodes-base.postgres", "typeVersion": 3.3, "position": [740, 500], "credentials": {"postgres": {"id": "postgis-credentials", "name": "PostGIS Credentials"}}, "notes": "Outil IA: Recherche un dossier par sa r\u00e9f\u00e9rence."}]', '{"trigger": {"main": [[{"node": "agent", "type": "main", "index": 0}]]}, "agent": {"main": [[{"node": "search_bien_by_ref", "type": "main", "index": 0}], [{"node": "analyse_bien_details", "type": "main", "index": 1}], [{"node": "search_dossier_by_ref", "type": "main", "index": 2}]]}, "search_bien_by_ref": {"main": [[{"node": "agent", "type": "main", "index": 0}]]}, "analyse_bien_details": {"main": [[{"node": "agent", "type": "main", "index": 0}]]}, "search_dossier_by_ref": {"main": [[{"node": "agent", "type": "main", "index": 0}]]}}', '{}', '0cdfe186-ac21-4a4b-8244-079c63dea22a', NOW(), NOW(), 1);

